export default JSON.parse("{\"schema\":\"ai-brain-implementation-pattern/1.0\",\"domain\":\"studio-tools\",\"capabilities\":[\"3d\",\"character\",\"class\",\"effect\",\"layer\",\"mask\",\"merge\",\"shape\",\"sort\"],\"provenance\":{\"sourceGroup\":\"character-voice-studio\",\"sourceType\":\"implementation-pattern-extraction\"},\"sourceLanguage\":\"py\",\"summary\":{\"functions\":[\"__init__\",\"calculate_post_conv_height\",\"forward\"],\"classes\":[\"CapacitronVAE\",\"PostEncoderMLP\",\"ReferenceEncoder\",\"TextSummary\"],\"imports\":[],\"lineCount\":206,\"characterCount\":9388},\"selectedComments\":[\"Init distributions\",\"define output ReferenceEncoder dim to the capacitron_VAE_embedding_dim\",\"Init beta, the lagrange-like term for the KL distribution\",\"TODO: Test a multispeaker model!\",\"Use reference\",\"concat speaker_embedding and/or text summary embedding\",\"Feed the output of the ref encoder and information about text/speaker into\",\"an MLP to produce the parameteres for the approximate poterior distributions\",\"convert to cpu because prior_distribution was created on cpu\",\"Sample from the posterior: z ~ q(z|x)\",\"Infer from the model, bypasses encoding\",\"Sample from the prior: z ~ p(z)\",\"reshape to [batch_size, 1, capacitron_VAE_embedding_dim]\",\"Create the post conv width mask based on the valid lengths of the output of the convolution.\",\"The valid lengths for the output of a convolution on varying length inputs is\",\"ceil(input_length/stride) + 1 for stride=3 and padding=2\",\"For example (kernel_size=3, stride=2, padding=2):\",\"0 0 x x x x x 0 0 -> Input = 5, 0 is zero padding, x is valid values coming from padding=2 in conv2d\",\" x _____\",\" x _____\",\" x  ____\",\"       x\",\"x x x x -> Output valid length = 4\",\"Since every example in te batch is zero padded and therefore have separate valid_lengths,\",\"we need to mask off all the values AFTER the valid length for each example in the batch.\",\"Otherwise, the convolutions create noise and a lot of not real information\",\"x: 4D tensor [batch_size, post_conv_width,\",\"num_channels==128, post_conv_height]\",\"x: 3D tensor [batch_size, post_conv_width,\",\"num_channels*post_conv_height]\",\"Routine for fetching the last valid output of a dynamic LSTM with varying input lengths and padding\",\"Routine for fetching the last valid output of a dynamic LSTM with varying input lengths and padding\",\"The mean parameter is unconstrained\",\"The standard deviation must be positive. Parameterise with a softplus\"]}");
